#!/usr/bin/env python3
"""comfy-gate: add the workbench "库" (library of on-demand custom nodes / models) – /_gate/library.

Run on the VPS as root:   python3 gate-library.py /opt/comfy-colab-kit
then:                     docker restart comfy-gate

Safe to run twice; keeps .bak copies; aborts without changing anything if the code
doesn't look as expected. Works with or without gate-gpu-select.py applied.
"""
import pathlib
import sys

ROOT = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
LIBRARY_PY = '"""User library of on-demand custom nodes and models.\n\nEvery wake is a fresh Colab VM, so nothing installed through ComfyUI-Manager survives a stop.\nThe library keeps the *list* (STATE_DIR/library.json, written by owners through /_gate/library)\nand installs entries onto the running VM only when asked (POST /_gate/library/install) or,\nfor entries flagged ``auto_wake``, as part of every boot. Installation reuses the on-demand\nfetch path of setup.py (parallel downloader, custom-node install); new custom nodes trigger a\nComfyUI restart so they register without a new wake.\n"""\nfrom __future__ import annotations\n\nimport json\nimport re\nimport urllib.request\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .profiles import hf_to_https\n\nKINDS = ("node", "model")\n_SLUG = re.compile(r"[^a-z0-9_-]+")\n_DEST = re.compile(r"^[A-Za-z0-9_.\\- ]+(/[A-Za-z0-9_.\\- ]+)+$")\n_SECRET = re.compile(r"(hf_[A-Za-z0-9]{20,}|ghp_[A-Za-z0-9]{20,}|token=|access_token|ya29\\.)", re.I)\n\n\nclass LibraryError(ValueError):\n    pass\n\n\ndef _path(state_dir: str) -> Path:\n    return Path(state_dir) / "library.json"\n\n\ndef load(state_dir: str) -> list[dict]:\n    p = _path(state_dir)\n    if not p.is_file():\n        return []\n    try:\n        d = json.loads(p.read_text())\n    except ValueError:\n        return []\n    return [i for i in d.get("items", []) if isinstance(i, dict) and i.get("id")]\n\n\ndef save(state_dir: str, items: list[dict]) -> None:\n    p = _path(state_dir)\n    p.parent.mkdir(parents=True, exist_ok=True)\n    tmp = p.with_suffix(".tmp")\n    tmp.write_text(json.dumps({"items": items}, ensure_ascii=False, indent=1))\n    tmp.replace(p)\n\n\ndef slug(s: str) -> str:\n    return _SLUG.sub("-", s.lower()).strip("-")[:48] or "item"\n\n\ndef normalize(raw: dict[str, Any]) -> dict:\n    """Validate one entry coming from a client. Raises LibraryError with a readable message."""\n    kind = str(raw.get("kind", "")).strip()\n    if kind not in KINDS:\n        raise LibraryError("kind must be \'node\' or \'model\'")\n    url = str(raw.get("url", "")).strip()\n    if not (url.startswith("https://") or url.startswith("hf://")):\n        raise LibraryError("url must start with https:// or hf://")\n    if _SECRET.search(url):\n        raise LibraryError("url looks like it contains a credential; use a public URL")\n    title = str(raw.get("title") or "").strip()[:80]\n    item: dict[str, Any] = {"kind": kind, "url": url, "auto_wake": bool(raw.get("auto_wake"))}\n    if kind == "node":\n        base = url.rstrip("/").rsplit("/", 1)[-1].removesuffix(".git")\n        item["title"] = title or base\n        item["id"] = slug(str(raw.get("id") or base))\n        for k in ("ref", "subdir"):\n            v = str(raw.get(k) or "").strip()\n            if v:\n                if ".." in v or v.startswith("/"):\n                    raise LibraryError(f"bad {k}")\n                item[k] = v\n    else:\n        dest = str(raw.get("dest", "")).strip().strip("/")\n        if not _DEST.match(dest) or ".." in dest:\n            raise LibraryError("dest must look like \'folder/file.safetensors\' (relative to ComfyUI/models)")\n        item["dest"] = dest\n        item["title"] = title or dest.rsplit("/", 1)[-1]\n        item["id"] = slug(str(raw.get("id") or dest.replace("/", "-")))\n        size = raw.get("size_gb")\n        if isinstance(size, (int, float)) and size > 0:\n            item["size_gb"] = round(float(size), 3)\n        sha = str(raw.get("sha256") or "").strip().lower()\n        if re.fullmatch(r"[0-9a-f]{64}", sha):\n            item["sha256"] = sha\n    lic = str(raw.get("license") or "").strip()[:40]\n    if lic:\n        item["license"] = lic\n    note = str(raw.get("note") or "").strip()[:200]\n    if note:\n        item["note"] = note\n    return item\n\n\ndef probe_size_gb(url: str, timeout: float = 10) -> float | None:\n    """Best effort: HEAD the (redirect-following) URL for Content-Length."""\n    try:\n        req = urllib.request.Request(hf_to_https(url), method="HEAD", headers={"User-Agent": "comfy-gate"})\n        with urllib.request.urlopen(req, timeout=timeout) as r:  # noqa: S310 (user-supplied public URL)\n            n = int(r.headers.get("Content-Length") or 0)\n            return round(n / 1e9, 3) if n > 0 else None\n    except Exception:  # noqa: BLE001\n        return None\n\n\ndef upsert(items: list[dict], item: dict) -> list[dict]:\n    out = [i for i in items if i["id"] != item["id"]]\n    out.append(item)\n    return out\n\n\ndef _model_entry(it: dict) -> dict:\n    return {"id": "lib-" + it["id"], "dest": it["dest"], "url": hf_to_https(it["url"]), "sha256": it.get("sha256"),\n            "size_gb": it.get("size_gb") or 0, "core": False}\n\n\ndef _node_entry(it: dict) -> dict:\n    return {"id": it["id"], "url": it["url"], "ref": it.get("ref"), "subdir": it.get("subdir")}\n\n\ndef fetch_plan(base_plan: dict, items: list[dict]) -> dict:\n    """On-demand install plan for a running VM (setup.py fetch_only path)."""\n    plan = dict(base_plan)\n    plan["models"] = [_model_entry(i) for i in items if i["kind"] == "model"]\n    plan["custom_nodes"] = [_node_entry(i) for i in items if i["kind"] == "node"]\n    plan["workflows"] = []\n    plan["fetch_only"] = True\n    plan["smoke"] = None\n    plan["library_ids"] = [i["id"] for i in items]\n    plan["restart_comfy"] = any(i["kind"] == "node" for i in items)\n    return plan\n\n\ndef merge_into_boot(plan: dict, items: list[dict]) -> list[str]:\n    """Add auto_wake entries to a boot plan (nodes before ComfyUI starts, models in the background)."""\n    have_nodes = {n["id"] for n in plan.get("custom_nodes", [])}\n    have_models = {m["dest"] for m in plan.get("models", [])}\n    added = []\n    for it in items:\n        if it["kind"] == "node" and it["id"] not in have_nodes:\n            plan.setdefault("custom_nodes", []).append(_node_entry(it))\n        elif it["kind"] == "model" and it["dest"] not in have_models:\n            plan.setdefault("models", []).append(_model_entry(it))\n        else:\n            continue\n        added.append(it["id"])\n    return added\n'
TEST_PY = 'import json\n\nimport pytest\n\nfrom gate import library\n\n\ndef test_normalize_node_and_model():\n    n = library.normalize({"kind": "node", "url": "https://github.com/numz/ComfyUI-SeedVR2_VideoUpscaler.git"})\n    assert n["id"] == "comfyui-seedvr2_videoupscaler" and n["title"] == "ComfyUI-SeedVR2_VideoUpscaler"\n    m = library.normalize({"kind": "model", "url": "hf://numz/SeedVR2_comfyUI/ema_vae_fp16.safetensors",\n                           "dest": "SEEDVR2/ema_vae_fp16.safetensors", "size_gb": 0.5, "auto_wake": 1})\n    assert m["id"] == "seedvr2-ema_vae_fp16-safetensors" and m["auto_wake"] is True and m["size_gb"] == 0.5\n\n\n@pytest.mark.parametrize("bad", [\n    {"kind": "x", "url": "https://a/b"},\n    {"kind": "node", "url": "http://insecure/x"},\n    {"kind": "node", "url": "https://h/x?token=abc"},\n    {"kind": "model", "url": "https://h/x.bin", "dest": "../etc/passwd"},\n    {"kind": "model", "url": "https://h/x.bin", "dest": "nofolder.bin"},\n])\ndef test_normalize_rejects(bad):\n    with pytest.raises(library.LibraryError):\n        library.normalize(bad)\n\n\ndef test_store_roundtrip_and_plans(tmp_path):\n    sd = str(tmp_path)\n    node = library.normalize({"kind": "node", "url": "https://github.com/a/node-x"})\n    model = library.normalize({"kind": "model", "url": "hf://o/r/m.safetensors", "dest": "SEEDVR2/m.safetensors",\n                               "auto_wake": True})\n    library.save(sd, library.upsert(library.upsert([], node), model))\n    items = library.load(sd)\n    assert {i["id"] for i in items} == {node["id"], model["id"]}\n    base = {"profile": "p", "comfyui": {}, "models": [{"id": "core", "dest": "a/b", "core": True}],\n            "custom_nodes": [], "workflows": [{"id": "w"}], "smoke": {"x": 1}}\n    fp = library.fetch_plan(base, items)\n    assert fp["fetch_only"] and fp["restart_comfy"] and fp["workflows"] == [] and fp["smoke"] is None\n    assert [m["dest"] for m in fp["models"]] == ["SEEDVR2/m.safetensors"]\n    assert fp["models"][0]["url"].startswith("https://huggingface.co/o/r/resolve/")\n    assert sorted(fp["library_ids"]) == sorted([node["id"], model["id"]])\n    boot = json.loads(json.dumps(base))\n    added = library.merge_into_boot(boot, [i for i in items if i.get("auto_wake")])\n    assert added == [model["id"]] and boot["models"][-1]["core"] is False\n\n\nasync def test_library_endpoints_and_install(tmp_path):\n    import asyncio\n\n    from tests.test_app import client\n    from gate.app import SESSION\n    from gate.state import State\n\n    c, app = await client(tmp_path)\n    try:\n        r = await c.post("/_gate/library", json={"kind": "node", "url": "https://github.com/a/node-x"})\n        assert r.status == 200 and (await r.json())["id"] == "node-x"\n        r = await c.post("/_gate/library", json={"kind": "model", "url": "https://h/m.bin", "dest": "x/m.bin",\n                                                 "size_gb": 1, "auto_wake": True})\n        mid = (await r.json())["id"]\n        r = await c.post("/_gate/library", json={"kind": "model", "url": "https://h/m.bin", "dest": "../x"})\n        assert r.status == 400\n        r = await c.get("/_gate/library")\n        assert {i["id"] for i in (await r.json())["items"]} == {"node-x", mid}\n        r = await c.post("/_gate/library/install", json={"ids": ["node-x"]})\n        assert r.status == 409  # asleep\n        # wake: the auto_wake model joins the boot plan and counts as installed\n        await c.post("/_gate/wake", json={"profile": "tiny"})\n        s = app[SESSION]\n        for _ in range(200):\n            if s.machine.state == State.READY:\n                break\n            await asyncio.sleep(0.02)\n        assert s.machine.state == State.READY and s.lib_installed == [mid]\n        s.colab.lines = [\'KIT_FETCHED {"workflows": [], "library": ["node-x"]}\']\n        r = await c.post("/_gate/library/install", json={"ids": ["node-x"]})\n        assert r.status == 202\n        for _ in range(100):\n            if not s.fetching:\n                break\n            await asyncio.sleep(0.02)\n        assert "node-x" in s.lib_installed\n        r = await c.post("/_gate/library/install", json={"ids": ["nope"]})\n        assert r.status == 404\n        r = await c.delete("/_gate/library/node-x")\n        assert r.status == 200\n    finally:\n        await c.close()\n'
APP = [('from . import __version__\n', 'from . import __version__, library\n'), ('async def switch(request: web.Request) -> web.Response:\n', 'async def library_list(request: web.Request) -> web.Response:\n    """GET /_gate/library: saved on-demand nodes/models + what is on the current VM."""\n    s = request.app[SESSION]\n    return web.json_response({"items": library.load(request.app[SETTINGS].state_dir),\n                              "installed": list(s.lib_installed), "fetching": list(s.fetching),\n                              "fetch_error": s.fetch_error})\n\n\nasync def library_add(request: web.Request) -> web.Response:\n    """POST /_gate/library {kind, url, title?, dest? (models), ref?, subdir?, auto_wake?}: add or update."""\n    ident = _ident(request)\n    try:\n        authorize(ident, "wake", request.app[SETTINGS])\n    except AuthError as e:\n        return err(e.status, e.code, e.msg)\n    body = await _body(request)\n    try:\n        item = library.normalize(body)\n    except library.LibraryError as e:\n        return err(400, "bad_request", str(e))\n    if item["kind"] == "model" and "size_gb" not in item:\n        size = await asyncio.get_running_loop().run_in_executor(None, library.probe_size_gb, item["url"])\n        if size:\n            item["size_gb"] = size\n    sd = request.app[SETTINGS].state_dir\n    library.save(sd, library.upsert(library.load(sd), item))\n    return web.json_response(item)\n\n\nasync def library_delete(request: web.Request) -> web.Response:\n    ident = _ident(request)\n    try:\n        authorize(ident, "wake", request.app[SETTINGS])\n    except AuthError as e:\n        return err(e.status, e.code, e.msg)\n    sd = request.app[SETTINGS].state_dir\n    iid = request.match_info["id"]\n    items = library.load(sd)\n    if not any(i["id"] == iid for i in items):\n        return err(404, "unknown_item", "no such library item")\n    library.save(sd, [i for i in items if i["id"] != iid])\n    return web.json_response({"deleted": iid})\n\n\nasync def library_install(request: web.Request) -> web.Response:\n    """POST /_gate/library/install {"ids": [...]}: install onto the running VM (nodes trigger a ComfyUI restart)."""\n    ident = _ident(request)\n    try:\n        authorize(ident, "wake", request.app[SETTINGS])\n    except AuthError as e:\n        return err(e.status, e.code, e.msg)\n    body = await _body(request)\n    ids = body.get("ids")\n    if not isinstance(ids, list) or not ids or not all(isinstance(i, str) for i in ids):\n        return err(400, "bad_request", "body must be {\\"ids\\": [\\"<id>\\", ...]}")\n    why = await request.app[SESSION].install_library(ids)\n    if why:\n        return err(404 if why == "unknown_item" else 409, why, f"install refused: {why}")\n    return web.json_response({"installing": ids}, status=202)\n\n\nasync def switch(request: web.Request) -> web.Response:\n'), ('    r.add_post("/_gate/fetch", fetch)\n', '    r.add_post("/_gate/fetch", fetch)\n    r.add_get("/_gate/library", library_list)\n    r.add_post("/_gate/library", library_add)\n    r.add_post("/_gate/library/install", library_install)\n    r.add_delete("/_gate/library/{id}", library_delete)\n')]
SESSION = [('from . import stopper\n', 'from . import library, stopper\n'), ('        self.fetch_error = ""\n        self._last_accrual = clock()\n', '        self.fetch_error = ""\n        self.lib_installed: list[str] = []  # library entries present on the current VM\n        self._last_accrual = clock()\n'), ('                       "fetch_error": self.fetch_error},\n        }\n', '                       "fetch_error": self.fetch_error},\n            "library": {"installed": list(self.lib_installed)},\n        }\n'), ('    async def _fetch(self, plan: dict) -> None:\n', '    async def install_library(self, ids: list[str]) -> str:\n        """Install library entries (custom nodes / models) onto the running VM. Returns \'\' or a refusal."""\n        m = self.machine\n        if m.state != State.READY or not m.profile:\n            return "not_ready"\n        if self._fetch_task and not self._fetch_task.done():\n            return "fetch_in_progress"\n        lib = {i["id"]: i for i in library.load(self.settings.state_dir)}\n        items = [lib[i] for i in ids if i in lib]\n        if not items or len(items) != len(set(ids)):\n            return "unknown_item"\n        plan = library.fetch_plan(build_plan(self.profiles[m.profile], self.settings), items)\n        self.fetching, self.fetch_error = ["lib:" + i["id"] for i in items], ""\n        self.bus.publish("state", self.status())\n        self._fetch_task = asyncio.create_task(self._fetch(plan))\n        return ""\n\n    async def _fetch(self, plan: dict) -> None:\n'), ('        self.on_demand, self.fetching = [], []\n', '        self.on_demand, self.fetching = [], []\n        self.lib_installed = []\n'), ('                self.on_demand = [w for w in self.on_demand if w not in (d.get("workflows") or [])]\n', '                self.on_demand = [w for w in self.on_demand if w not in (d.get("workflows") or [])]\n                self.lib_installed = sorted(set(self.lib_installed) | set(d.get("library") or []))\n'), ('            self.on_demand, self.fetching, self.fetch_error = sorted(plan.get("on_demand") or {}), [], ""\n', '            self.on_demand, self.fetching, self.fetch_error = sorted(plan.get("on_demand") or {}), [], ""\n            auto = [i for i in library.load(self.settings.state_dir) if i.get("auto_wake")]\n            self.lib_installed = sorted(library.merge_into_boot(plan, auto)) if auto else []\n')]
SETUP = [('def install_custom_nodes():\n    base = ', 'def install_custom_nodes():\n    """Install the plan\'s custom nodes; returns the ids that were newly installed."""\n    new = []\n    base = '), ('pip install -q -r {dst}/requirements.txt", check=False)\n\n\ndef start_tunnel():', 'pip install -q -r {dst}/requirements.txt", check=False)\n        new.append(n["id"])\n    return new\n\n\ndef start_tunnel():'), ('        install_custom_nodes()\n        install_workflows(update_default=False)\n', '        new_nodes = install_custom_nodes()\n        install_workflows(update_default=False)\n'), ('        dl.wait([m["id"] for m in PLAN["models"]])\n    except Exception as e:  # noqa: BLE001\n        print(f"KIT_FETCH_FAILED', '        dl.wait([m["id"] for m in PLAN["models"]])\n        if PLAN.get("restart_comfy") and new_nodes:\n            restart_comfy()\n    except Exception as e:  # noqa: BLE001\n        print(f"KIT_FETCH_FAILED'), ('    print(f"KIT_FETCHED {json.dumps({\'workflows\': ids})}", flush=True)\n', '    print(f"KIT_FETCHED {json.dumps({\'workflows\': ids, \'library\': PLAN.get(\'library_ids\') or []})}", flush=True)\n\n\ndef restart_comfy():\n    """Restart ComfyUI in place so freshly installed custom nodes register (library installs)."""\n    print("KIT_LIB restarting ComfyUI to load new custom nodes", flush=True)\n    subprocess.run(["bash", "-lc", "pkill -f \'main.py --listen\' || true"], check=False)\n    for _ in range(30):\n        if not up():\n            break\n        time.sleep(1)\n    cfg = PLAN["comfyui"]\n    cenv = {**os.environ, **{k: str(v) for k, v in (cfg.get("env") or {}).items()}}\n    cenv.pop("CF_TUNNEL_TOKEN", None)\n    cenv.pop("HF_TOKEN", None)\n    subprocess.Popen(comfy_cmd(), cwd=COMFY, env=cenv, stdout=open(f"{LOG}/comfyui.log", "a"),\n                     stderr=subprocess.STDOUT, start_new_session=True)\n    for _ in range(300):\n        if up():\n            print("KIT_LIB ComfyUI restarted", flush=True)\n            return\n        time.sleep(1)\n    raise RuntimeError("ComfyUI did not come back after restart")\n')]
FILES = [("apps/gate/app.py", APP, "library_list"), ("apps/gate/session.py", SESSION, "lib_installed"),
         ("packages/colab/setup.py", SETUP, "def restart_comfy")]


def main():
    if not (ROOT / "apps/gate/session.py").is_file():
        sys.exit(f"✗ {ROOT} is not the comfy-colab-kit folder – run: python3 gate-library.py /opt/comfy-colab-kit")
    if "def hf_to_https" not in (ROOT / "apps/gate/profiles.py").read_text():
        sys.exit("✗ this gate version has no hf_to_https – send this output to the Wakeloom maintainer. Nothing was changed.")
    todo = []
    for rel, edits, mark in FILES:
        p = ROOT / rel
        src = p.read_text(encoding="utf-8")
        if mark in src:
            print(f"= {rel} already patched")
            continue
        out = src
        for old, new in edits:
            n = out.count(old)
            if n != 1:
                sys.exit(f"✗ {rel}: expected 1 match, found {n}:\n    {old.strip()[:90]}\nNothing was changed. Send this output to the Wakeloom maintainer.")
            out = out.replace(old, new)
        compile(out, str(p), "exec")
        todo.append((p, out))
    for p, out in todo:
        p.with_suffix(p.suffix + ".bak").write_bytes(p.read_bytes())
        p.write_text(out, encoding="utf-8")
        print(f"✓ patched {p.relative_to(ROOT)} (backup: {p.name}.bak)")
    lp = ROOT / "apps/gate/library.py"
    if lp.exists() and lp.read_text() == LIBRARY_PY:
        print("= apps/gate/library.py already present")
    else:
        lp.write_text(LIBRARY_PY, encoding="utf-8")
        print("✓ wrote apps/gate/library.py")
    tp = ROOT / "tests/test_library.py"
    if tp.parent.is_dir():
        tp.write_text(TEST_PY, encoding="utf-8")
    print("Done. Now run:  docker restart comfy-gate")


main()
